    rentals: Vec<Rental>,
}
impl Customer {
    fn statement(&self) -> String {
        let mut total = 0.0;
        for r in &self.rentals {
            let mut amt = 0.0;
            match r.movie.price_code {
                0 => { // REGULAR
                    amt += 2.0;
                    if r.days_rented > 2 {
                        amt += (r.days_rented - 2) as f64 * 1.5;
                    }
                }
                1 => { // NEW_RELEASE
                    amt += r.days_rented as f64 * 3.0;
                }
                _ => {}
            }
            total += amt;
        }
        format!("Amount owed: {}", total)
    }
}
